// Script to generate placeholder asset images
const fs = require('fs');
const path = require('path');

// Minimal valid PNG files (1x1 pixel transparent PNG)
const createMinimalPng = () => {
  return Buffer.from(
    'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8DwHwAFBQIAX8jx0gAAAABJRU5ErkJggg==',
    'base64'
  );
};

// Create a simple blue PNG (base64 of a 512x512 blue square)
const bluePng = Buffer.from(
  '',
    'base64'
  );

const assetsDir = path.join(__dirname, 'assets');

if (!fs.existsSync(assetsDir)) {
  fs.mkdirSync(assetsDir, { recursive: true });
}

// Write all asset files
fs.writeFileSync(path.join(assetsDir, 'icon.png'), bluePng);
fs.writeFileSync(path.join(assetsDir, 'favicon.png'), bluePng);
fs.writeFileSync(path.join(assetsDir, 'adaptive-icon.png'), bluePng);
fs.writeFileSync(path.join(assetsDir, 'splash.png'), bluePng);

console.log('✅ Asset files created successfully!');
console.log('   - icon.png');
console.log('   - favicon.png');
console.log('   - adaptive-icon.png');
console.log('   - splash.png');
